import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { Box, Spinner, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import type { ContentfulClientApi } from 'contentful';
import { ExperienceRoot, useFetchById } from '@contentful/experiences-sdk-react';
import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import Seo from '@salesforce/retail-react-app/app/components/seo';
import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import { CONTENTFUL_FALLBACK_LOCALE, CONTENTFUL_LIVE_PREVIEW_ORIGIN } from '../../config/contentful';
import { useContentfulClient } from '../../hooks/useContentfulClient';

// Side-effect import — registers experience components with the Contentful Experiences SDK
import '../../components/contentful/experiences/definitions';

type ExperienceViewProps = {
  client: ContentfulClientApi<any>;
  entryId: string;
  experienceTypeId: string;
  locale: string;
};

/** Fetches and renders the experience once we know its content type ID. */
const ExperienceView = ({ client, entryId, experienceTypeId, locale }: ExperienceViewProps) => {
  const { experience, isLoading, error } = useFetchById({
    client: client as any,
    id: entryId,
    experienceTypeId,
    localeCode: locale,
  });

  if (isLoading) {
    return (
      <Box p={8} display="flex" justifyContent="center">
        <Spinner size="xl" />
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={8}>
        <Text color="red.500">Failed to load preview: {error.message}</Text>
      </Box>
    );
  }

  if (!experience) {
    return (
      <Box p={8}>
        <Text color="orange.500">
          Entry found (type: <strong>{experienceTypeId}</strong>) but it could not be rendered as a Contentful
          Experience. Make sure the content type is configured as an Experience Type in your Contentful space and that
          the entry is valid.
        </Text>
      </Box>
    );
  }

  return <ExperienceRoot experience={experience} locale={locale} />;
};

type ContentfulPreviewPageProps = {
  // The Contentful SDK's client generic is intentionally loose here — matches ExperienceView and
  // the Experiences SDK, which accept a broadly-typed client.
  client: ContentfulClientApi<any> | null;
  entryId: string;
  locale: string;
};

/**
 * Resolves the entry's content type first (without a type filter), then delegates
 * to ExperienceView with the correct experienceTypeId so useFetchById can query
 * successfully regardless of which Experience content type the entry belongs to.
 */
const ContentfulPreviewPage = ({ client, entryId, locale }: ContentfulPreviewPageProps) => {
  const [experienceTypeId, setExperienceTypeId] = useState<string | null>(null);
  const [typeError, setTypeError] = useState<string | null>(null);

  useEffect(() => {
    if (!client || !entryId) return;
    let active = true;
    setExperienceTypeId(null);
    setTypeError(null);
    client
      .getEntry(entryId)
      .then((entry) => {
        if (!active) return;
        setExperienceTypeId(entry.sys.contentType.sys.id);
      })
      .catch((err: unknown) => {
        if (!active) return;
        const msg = err instanceof Error ? err.message : String(err);
        setTypeError(`Could not load entry: ${msg}`);
      });
    return () => {
      active = false;
    };
  }, [client, entryId]);

  if (!client) {
    return (
      <Box p={8}>
        <Text color="red.500">Contentful configuration is missing.</Text>
      </Box>
    );
  }

  if (typeError) {
    return (
      <Box p={8}>
        <Text color="red.500">{typeError}</Text>
      </Box>
    );
  }

  if (!experienceTypeId) {
    return (
      <Box p={8} display="flex" justifyContent="center">
        <Spinner size="xl" />
      </Box>
    );
  }

  return <ExperienceView client={client} entryId={entryId} experienceTypeId={experienceTypeId} locale={locale} />;
};

const ContentfulPreview = () => {
  const { search } = useLocation();
  const params = new URLSearchParams(search);
  const entryId = params.get('entry') ?? '';

  // Locale priority: ?locale= query param (Contentful injects {locale} in preview URLs)
  // → active site locale from useMultiSite → fallback
  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
  const locale = params.get('locale') || siteLocale?.id || CONTENTFUL_FALLBACK_LOCALE;

  const { res } = useServerContext();
  const { client, previewUnavailable } = useContentfulClient({ preview: true });

  // Gate: if no preview token is configured this is not a preview-enabled environment.
  // Return 404 so the route is inert on staging/prod even if accidentally visited.
  if (previewUnavailable) {
    if (res) {
      res.status(404);
    }
    return (
      <>
        <Seo noIndex />
        <Box p={8}>
          <Text color="red.500">Not found.</Text>
        </Box>
      </>
    );
  }

  if (!entryId) {
    return (
      <>
        {/* noindex — editor-only route; keep every exit path out of the index */}
        <Seo noIndex />
        <Box p={8}>
          <Text color="red.500">Missing &quot;entry&quot; query parameter.</Text>
        </Box>
      </>
    );
  }

  return (
    <>
      {/* noindex — this route is for Contentful editors only, not public */}
      <Seo noIndex />
      <ContentfulLivePreviewProvider
        locale={locale}
        enableInspectorMode={true}
        enableLiveUpdates={true}
        targetOrigin={CONTENTFUL_LIVE_PREVIEW_ORIGIN}
      >
        <ContentfulPreviewPage client={client} entryId={entryId} locale={locale} />
      </ContentfulLivePreviewProvider>
    </>
  );
};

ContentfulPreview.getTemplateName = () => 'contentful-preview';

export default ContentfulPreview;

